request("https://bar.dayesteel.com.cn/api/api/bdy/bptdatcutopact/getsettingvalue?ProductLine=B1",{},'POST')
.then(data => {
    const group = data.Data;
    for (const tagName in group) {
        let val = group[tagName];
        // 限制3位小数，数字/字符串都兼容
        if (!isNaN(Number(val))) {
            val = Number(val).toFixed(3);
            // 如需数字类型去掉字符串，转Number：val = Number(val)
        }
        const node = view.dm().getDataByTag(tagName);
        if (node) {
            node.a('value', val);
        } else {
            console.warn(`未找到tag为【${tagName}】的拓扑节点`);
        }
    }
})
.catch(err => {
    console.error('获取锯切配置接口失败：', err);
});}

__ht__function(event, data, view) {// ============================================================
//  3#剪切台 — 锯片更换参数收集 & 校验
// ============================================================

// ===========================
// 1. 工具函数
// ===========================

/**
 * 获取当前日期时间字符串
 * 格式：YYYY-MM-DD HH:mm:ss
 * @returns {string}
 */
function getCurrentTimeWithMs() {
    const date = new Date();

    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');

    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const seconds = String(date.getSeconds()).padStart(2, '0');

    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

/**
 * 收集1#~3#锯的设定长度/实际位置/光栅位置/测量位置值
 * @returns {object} {Saw1LengthSetting: ..., Saw1ActualPosition: ..., ...}
 */
function getSawPositionValues() {
    var tags = [
        'Saw1LengthSetting', 'Saw1ActualPosition', 'Saw1GratingPosition', 'Saw1LengthActual',
        'Saw2LengthSetting', 'Saw2ActualPosition', 'Saw2GratingPosition', 'Saw2LengthActual',
        'Saw3LengthSetting', 'Saw3ActualPosition', 'Saw3GratingPosition', 'Saw3LengthActual'
    ];
    var result = {};
    tags.forEach(function(tag) {
        var node = dataModel.getDataByTag(tag);
        result[tag] = node ? Number(node.a('value')) : null;
    });
    return result;
}

// ===========================
// 2. 数据获取
// ===========================
//卡号信息
var cardNoTable = dataModel.getDataByTag('1#plan');
var cardNoInput = dataModel.getDataByTag('CardNo');
//卡号获取
var CardNo;
if(cardNoInput && cardNoInput.a('value')){
    CardNo = cardNoInput.a('value');
    showToast("输入框卡号获取成功",CardNo);
}else if(cardNoTable && cardNoTable.a('ht.dataSource')){
    var ds = cardNoTable.a('ht.dataSource');
    if (ds && ds.length > 0) CardNo = ds[0].CardNo;
    showToast("表格卡号获取成功",CardNo);
}
if(!CardNo){
    showToast("未获取到卡号");
}

// 锯位信息参数
var sawPosition = getSawPositionValues();

// 锯位选择（允许为空）
var btnGroupNode = dataModel.getDataByTag('SawMachineNumber');
var checkButton1 = btnGroupNode ? btnGroupNode.a('dataModel').toDatas(data => data.s('checked')).toArray() : [];
console.log(checkButton1)

// 厂家信息参数（与锯位选择同类组件，允许为空）
var bladeSupplierNode = dataModel.getDataByTag('BladeSupplier');
var checkBladeSupplier = bladeSupplierNode ? bladeSupplierNode.a('dataModel').toDatas(data => data.s('checked')).toArray() : [];
var BladeSupplier = null;
if (checkBladeSupplier.length > 0) {
    var supplierNames = [];
    checkBladeSupplier.forEach(function(btn) {
        supplierNames.push(btn._name);
    });
    BladeSupplier = supplierNames.join(',');
}

// 新旧锯片参数（3组6个）
var bladeParams = {};
['1#', '2#', '3#'].forEach(function(saw) {
    bladeParams[saw + 'OldBladeDiameter'] = dataModel.getDataByTag(saw + 'OldBladeDiameter');
    bladeParams[saw + 'NewBladeDiameter'] = dataModel.getDataByTag(saw + 'NewBladeDiameter');
});

//生产班组信息
var group = dataModel.getDataByTag('Group');
var shift = dataModel.getDataByTag('Shift');
var selectMode = dataModel.getDataByTag('SelectMode');
var remark = dataModel.getDataByTag('Remark');
var checkButton2 = selectMode ? selectMode.a('dataModel').toDatas(data => data.s('checked')).toArray() : [];


// 锯位选择（允许为空，支持多选），获取所有选中的锯号
var selectedSaws = [];
checkButton1.forEach(function(btn) {
    selectedSaws.push(btn._name); // 如 ["1#", "2#"]
});

// ===========================
// 3. 锯位-锯片直径联动校验（在参数拼接前）
// ===========================
// 遍历所有选中的锯位，检查对应的新旧锯片直径是否填写，收集所有有问题的锯位
var errorSaws = [];
selectedSaws.forEach(function(saw) {
    var oldNode = bladeParams[saw + 'OldBladeDiameter'];
    var newNode = bladeParams[saw + 'NewBladeDiameter'];
    var oldVal = oldNode ? oldNode.a('value') : null;
    var newVal = newNode ? newNode.a('value') : null;
    var oldEmpty = (oldVal === null || oldVal === undefined || oldVal === '');
    var newEmpty = (newVal === null || newVal === undefined || newVal === '');
    if (oldEmpty || newEmpty) {
        errorSaws.push(saw);
    }
});
// 有问题的锯位合并成一条提示，校验不通过则终止后续提交
if (errorSaws.length > 0) {
    showToast('已选中' + errorSaws.join('、') + '锯，未填写锯片直径');
    return;
}

// ===========================
// 4. 参数拼接
// ===========================

// 锯片更换参数（数组格式，每个锯位一条记录）
var bladeChangeTime = getCurrentTimeWithMs();
var bladeParamsArray = [];
selectedSaws.forEach(function(saw) {
    var oldNode = bladeParams[saw + 'OldBladeDiameter'];
    var newNode = bladeParams[saw + 'NewBladeDiameter'];
    bladeParamsArray.push({
        CardNo: CardNo,
        ShiftGroup: group.a('value'),
        ShiftNo: shift.a('value'),
        SawMachineNumber: saw,
        OldBladeDiameter: oldNode ? oldNode.a('value') : null,
        NewBladeDiameter: newNode ? newNode.a('value') : null,
        BladeChangeTime: bladeChangeTime,
        ProductLine: "B1",
        BladeSupplier: BladeSupplier
    });
});

// 原有提交参数
var sawMachineNumber = selectedSaws.length > 0 ? selectedSaws.join(',') : null;
var params = {
    CardNo: CardNo,
    ProductLine: "B1",
    SawMachineNumber: sawMachineNumber,
    ProductionTime: getCurrentTimeWithMs(),
    BladeChangeTime: bladeChangeTime,
    ShiftGroup: group.a('value'),
    ShiftNo: shift.a('value'),
    ShearMethod: checkButton2.length > 0 ? checkButton2[0]._name : null,
    Memo: remark.a('value'),
    ...sawPosition
};
console.log(params)

// ===========================
// 5. 参数空值检查 & 弹窗确认提交
// ===========================

// 需检查的字段（排除时间、备注）
var checkFields = {
    'CardNo':                    '卡号',
    'ProductLine':               '产线',
    'SawMachineNumber':          '锯位',
    'ShiftGroup':                '班组',
    'ShiftNo':                   '班次',
    'ShearMethod':               '剪切方式',
    'Saw1LengthSetting':         '1#锯设定值',
    'Saw1ActualPosition':        '1#锯实际位置',
    'Saw1GratingPosition':       '1#锯光栅位置',
    'Saw1LengthActual':          '1#锯测量位置',
    'Saw2LengthSetting':         '2#锯设定值',
    'Saw2ActualPosition':        '2#锯实际位置',
    'Saw2GratingPosition':       '2#锯光栅位置',
    'Saw2LengthActual':          '2#锯测量位置',
    'Saw3LengthSetting':         '3#锯设定值',
    'Saw3ActualPosition':        '3#锯实际位置',
    'Saw3GratingPosition':       '3#锯光栅位置',
    'Saw3LengthActual':          '3#锯测量位置'
};

var emptyFields = [];
for (var key in checkFields) {
    var v = params[key];
    if (v === null || v === undefined || v === '' || (typeof v === 'number' && isNaN(v))) {
        emptyFields.push(checkFields[key]);
    }
}

var confirmContent;
if (emptyFields.length > 0) {
    confirmContent = emptyFields.join('、') + "为空，是否提交？";
} else {
    confirmContent = "确认提交？";
}

DialogSystem.open({
    title: "提交确认",
    content: confirmContent,
    url: "https://bar.dayesteel.com.cn/api/api/bdy/bptdatcutopact/create",
    params: params,
    requestFn: function(url, params) {
        // 先提交原长度信息接口
        return request(url, params, 'PUT').then(function(result) {
            // 原接口成功后，如有选中锯位，再提交锯片更换接口
            if (bladeParamsArray.length > 0) {
                return request('https://bar.dayesteel.com.cn/api/api/bdy/bptdatbladechangeact/batchcreate', bladeParamsArray, 'PUT');
            }
            return result;
        });
    },
    onSuccess: function(result) {
        showToast("提交成功");
        // 接口操作成功后，刷新表格数据
        request('https://bar.dayesteel.com.cn/api/api/bdy/bptdatcutopact/fetchcardinfo?ProductLine=B1', {}, 'POST')
        .then(function(data) {
            var table = dataModel.getDataByTag('1#plan');
            if (table && data && data.Data) {
                table.a('ht.dataSource', data.Data);
            }
        })
        .catch(function(err) {
            console.error('表格刷新失败:', err);
        });
    },
    onFail: function(error) {
        showToast("提交失败：" + error);
    }
});}
